"""Coverage for defect #11's remaining gap: no cover-page (שער) support.

`generate_docx()` gains an entirely optional top-level `coverPage` object.
When absent, behavior must be byte-for-byte identical to before this
change (hard "no regression" guarantee). When present, it renders a
centered cover page -- university/faculty/department, title (falls back to
the top-level article title), author/studentId/supervisor/course/date, and
an AI-use disclosure (caller-supplied or a reviewable default constant) --
as the first page of the document, followed by a page break so the article
title always starts on a fresh page.
"""

from __future__ import annotations

import importlib.util
import os
import re
import tempfile
import unittest
import zipfile

from docx import Document

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCRIPTS_DIR = os.path.join(ROOT_DIR, "src", "scripts")


def _load_generate_docx_module():
    script_path = os.path.join(SCRIPTS_DIR, "generate-docx.py")
    spec = importlib.util.spec_from_file_location("generate_docx_module_cover_page_test", script_path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _text_runs(document_xml):
    return re.findall(r"<w:t[^>]*>([^<]*)</w:t>", document_xml)


def _base_data(**overrides):
    data = {
        "title": "כותרת המאמר",
        "totalWords": 100,
        "format": {"isRtl": True},
        "sections": [{"title": "מבוא", "paragraphs": ["פסקה קצרה."]}],
    }
    data.update(overrides)
    return data


def _generate(module, data):
    with tempfile.TemporaryDirectory() as tmpdir:
        output_path = os.path.join(tmpdir, "out.docx")
        module.generate_docx(data, output_path)
        with zipfile.ZipFile(output_path) as zf:
            document_xml = zf.read("word/document.xml").decode("utf-8")
        doc = Document(output_path)
        paragraphs = [p.text for p in doc.paragraphs]
        return document_xml, paragraphs


class CoverPageAbsentNoRegressionTests(unittest.TestCase):
    """coverPage absent vs. explicit None: both take the SAME (new) code
    path (the `if cover_page:` guard is falsy for both), so equality here
    confirms `None` is normalized the same as "key missing" -- it does not,
    by itself, prove parity with pre-change behavior. The actual "zero
    regression when coverPage is omitted" guarantee rests on: (1) the diff
    that added this feature is additive-only on every path a caller not
    passing `coverPage` can reach (new docstring lines, two new unused-until-
    called constants, a new function nothing calls unless `coverPage` is
    truthy, and a call site gated by `if data.get("coverPage"):`), and
    (2) every pre-existing test in tests/ -- none of which pass `coverPage`
    -- still passes unmodified. This class adds the same-path/no-phantom-
    -content checks on top of that.
    """

    def setUp(self):
        self.module = _load_generate_docx_module()

    def test_key_absent_and_key_none_are_normalized_identically(self):
        data_absent = _base_data()
        data_none = _base_data(coverPage=None)
        xml_absent, paras_absent = _generate(self.module, data_absent)
        xml_none, paras_none = _generate(self.module, data_none)
        self.assertEqual(xml_absent, xml_none)
        self.assertEqual(paras_absent, paras_none)

    def test_first_paragraph_is_the_article_title_no_phantom_cover_content(self):
        data = _base_data()
        _xml, paragraphs = _generate(self.module, data)
        non_empty = [p for p in paragraphs if p]
        self.assertEqual(non_empty[0], "כותרת המאמר")

    def test_no_page_break_emitted_when_cover_page_absent(self):
        data = _base_data()
        xml, _paragraphs = _generate(self.module, data)
        self.assertNotIn('<w:br w:type="page"/>', xml)


class CoverPageFullyPopulatedTests(unittest.TestCase):
    def setUp(self):
        self.module = _load_generate_docx_module()
        self.cover = {
            "university": "אוניברסיטת בר אילן",
            "faculty": "הפקולטה למדעי הרוח",
            "department": "המחלקה ללימודי ארץ ישראל",
            "title": "כותרת השער",
            "author": "ישראל ישראלי",
            "studentId": "123456789",
            "supervisor": "פרופ' כהן",
            "course": "סמינר מתקדם",
            "date": "תשפ״ה",  # gershayim -- matches validate_hebrew_text's own output
            "aiUseDeclaration": "הצהרה מפורשת על שימוש בבינה מלאכותית.",
        }
        self.data = _base_data(coverPage=self.cover)

    def test_every_populated_field_appears_in_document_xml(self):
        xml, _paragraphs = _generate(self.module, self.data)
        for key, value in self.cover.items():
            self.assertIn(value, xml, f"missing coverPage field {key!r} in output")

    def test_cover_fields_appear_before_the_article_title_in_document_order(self):
        xml, paragraphs = _generate(self.module, self.data)
        university_pos = xml.find(self.cover["university"])
        title_pos = xml.find("כותרת המאמר")
        self.assertNotEqual(university_pos, -1)
        self.assertNotEqual(title_pos, -1)
        self.assertLess(university_pos, title_pos)

        # Same check via paragraph order.
        non_empty = [p for p in paragraphs if p]
        university_idx = non_empty.index(self.cover["university"])
        article_title_idx = non_empty.index("כותרת המאמר")
        self.assertLess(university_idx, article_title_idx)

    def test_explicit_ai_use_declaration_is_used_verbatim(self):
        xml, _paragraphs = _generate(self.module, self.data)
        expected = self.module.validate_hebrew_text(self.cover["aiUseDeclaration"])
        self.assertIn(expected, xml)
        default_he = self.module.validate_hebrew_text(self.module.DEFAULT_AI_USE_DECLARATION_HE)
        self.assertNotIn(default_he, xml)

    def test_cover_title_falls_back_only_when_omitted(self):
        # Sanity: when the cover has its own title, that title -- not the
        # top-level article title -- is what renders in the cover block.
        _xml, paragraphs = _generate(self.module, self.data)
        self.assertIn("כותרת השער", paragraphs)


class CoverPagePartiallyPopulatedTests(unittest.TestCase):
    def setUp(self):
        self.module = _load_generate_docx_module()

    def test_only_populated_fields_render_no_none_or_empty_lines(self):
        data = _base_data(
            coverPage={
                "university": "אוניברסיטת בר אילן",
                "title": "כותרת השער",
                "faculty": None,
                "department": None,
                "author": None,
                "studentId": None,
                "supervisor": None,
                "course": None,
                "date": None,
            }
        )
        xml, paragraphs = _generate(self.module, data)
        self.assertNotIn("None", xml)
        self.assertIn("אוניברסיטת בר אילן", paragraphs)
        self.assertIn("כותרת השער", paragraphs)

        # Stronger check than substring presence: the 7 unset fields
        # (faculty/department/author/studentId/supervisor/course/date) must
        # not each leave behind an empty paragraph. The only paragraphs
        # before the article title should be exactly the 2 populated cover
        # fields, the default AI-use declaration, and the single empty
        # paragraph `doc.add_page_break()` itself produces -- nothing more.
        title_idx = paragraphs.index("כותרת המאמר")
        cover_paragraphs = paragraphs[:title_idx]
        default_declaration = self.module.validate_hebrew_text(self.module.DEFAULT_AI_USE_DECLARATION_HE)
        self.assertEqual(
            cover_paragraphs,
            ["אוניברסיטת בר אילן", "כותרת השער", default_declaration, ""],
        )

    def test_cover_title_falls_back_to_top_level_title_when_omitted(self):
        data = _base_data(
            coverPage={
                "university": "אוניברסיטת בר אילן",
            }
        )
        _xml, paragraphs = _generate(self.module, data)
        # The article title ("כותרת המאמר") appears twice: once in the
        # cover block (fallback) and once as the article's own heading.
        self.assertEqual(paragraphs.count("כותרת המאמר"), 2)


class CoverPagePageBreakTests(unittest.TestCase):
    def setUp(self):
        self.module = _load_generate_docx_module()

    def test_page_break_separates_cover_page_from_article_title(self):
        data = _base_data(coverPage={"university": "אוניברסיטת בר אילן"})
        xml, _paragraphs = _generate(self.module, data)
        self.assertIn('<w:br w:type="page"/>', xml)
        # The break must sit after the cover content and before the
        # article title in raw document order.
        break_pos = xml.find('<w:br w:type="page"/>')
        university_pos = xml.find("אוניברסיטת בר אילן")
        title_pos = xml.rfind("כותרת המאמר")  # last occurrence: the article heading
        self.assertNotEqual(break_pos, -1)
        self.assertLess(university_pos, break_pos)
        self.assertLess(break_pos, title_pos)
        # (no-cover-page case is covered by
        # CoverPageAbsentNoRegressionTests.test_no_page_break_emitted_when_cover_page_absent)


class CoverPageDefaultDeclarationTests(unittest.TestCase):
    """Assertions run the constant through `validate_hebrew_text` -- the
    same normalization every paragraph's text passes through in `add_para`
    -- rather than comparing against the raw constant. The constants
    currently contain no em-dash or straight quote, so this makes no
    difference today, but it means these tests keep tracking the rendered
    text (not a snapshot of today's punctuation) if a human edits the
    wording later to include either.
    """

    def setUp(self):
        self.module = _load_generate_docx_module()

    def test_default_hebrew_declaration_used_when_omitted_and_rtl(self):
        data = _base_data(coverPage={"university": "אוניברסיטת בר אילן"})
        xml, _paragraphs = _generate(self.module, data)
        expected = self.module.validate_hebrew_text(self.module.DEFAULT_AI_USE_DECLARATION_HE)
        self.assertIn(expected, xml)

    def test_default_english_declaration_used_when_omitted_and_ltr(self):
        data = _base_data(
            format={"isRtl": False},
            coverPage={"university": "Bar-Ilan University"},
        )
        xml, _paragraphs = _generate(self.module, data)
        expected = self.module.validate_hebrew_text(self.module.DEFAULT_AI_USE_DECLARATION_EN)
        self.assertIn(expected, xml)


if __name__ == "__main__":
    unittest.main()
